=head2 Google::Cloud::Contactcenterinsights::V1::Resources::PhraseMatcher

The phrase matcher resource.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

The resource name of the phrase matcher.
Format:
projects/{project}/locations/{location}/phraseMatchers/{phrase_matcher}

=item * C<< $msg->revision_id() >> / C<< $msg->revision_id($value) >>

Type: C<String>

Output only. Immutable. The revision ID of the phrase matcher.
A new revision is committed whenever the matcher is changed, except when it
is activated or deactivated. A server generated random ID will be used.
Example: locations/global/phraseMatchers/my-first-matcher@1234567

=item * C<< $msg->version_tag() >> / C<< $msg->version_tag($value) >>

Type: C<String>

The customized version tag to use for the phrase matcher. If not specified,
it will default to `revision_id`.

=item * C<< $msg->revision_create_time() >> / C<< $msg->revision_create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The timestamp of when the revision was created. It is also the
create time when a new matcher is added.

=item * C<< $msg->display_name() >> / C<< $msg->display_name($value) >>

Type: C<String>

The human-readable name of the phrase matcher.

=item * C<< $msg->type() >> / C<< $msg->type($value) >>

Type: C<Enum> (L<Google::Cloud::Contactcenterinsights::V1::PhraseMatcher::PhraseMatcherType>)

Required. The type of this phrase matcher.

=item * C<< $msg->active() >> / C<< $msg->active($value) >>

Type: C<Bool>

Applies the phrase matcher only when it is active.

=item * C<< $msg->phrase_match_rule_groups() >> / C<< $msg->phrase_match_rule_groups($value) >>

Type: C<Message> (L<Google::Cloud::Contactcenterinsights::V1::Resources::PhraseMatchRuleGroup>)

A list of phase match rule groups that are included in this matcher.

=item * C<< $msg->activation_update_time() >> / C<< $msg->activation_update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The most recent time at which the activation status was
updated.

=item * C<< $msg->role_match() >> / C<< $msg->role_match($value) >>

Type: C<Enum> (L<Google::Cloud::Contactcenterinsights::V1::ConversationParticipant::Role>)

The role whose utterances the phrase matcher should be matched
against. If the role is ROLE_UNSPECIFIED it will be matched against any
utterances in the transcript.

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The most recent time at which the phrase matcher was updated.

=back

