=head2 Google::Cloud::Contactcenterinsights::V1::Resources::AnnotatorSelector

Selector of all available annotators and phrase matchers to run.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->run_interruption_annotator() >> / C<< $msg->run_interruption_annotator($value) >>

Type: C<Bool>

Whether to run the interruption annotator.

=item * C<< $msg->run_silence_annotator() >> / C<< $msg->run_silence_annotator($value) >>

Type: C<Bool>

Whether to run the silence annotator.

=item * C<< $msg->run_phrase_matcher_annotator() >> / C<< $msg->run_phrase_matcher_annotator($value) >>

Type: C<Bool>

Whether to run the active phrase matcher annotator(s).

=item * C<< $msg->phrase_matchers() >> / C<< $msg->phrase_matchers($value) >>

Type: C<String>

The list of phrase matchers to run. If not provided, all active phrase
matchers will be used. If inactive phrase matchers are provided, they will
not be used. Phrase matchers will be run only if
run_phrase_matcher_annotator is set to true. Format:
projects/{project}/locations/{location}/phraseMatchers/{phrase_matcher}

=item * C<< $msg->run_sentiment_annotator() >> / C<< $msg->run_sentiment_annotator($value) >>

Type: C<Bool>

Whether to run the sentiment annotator.

=item * C<< $msg->run_entity_annotator() >> / C<< $msg->run_entity_annotator($value) >>

Type: C<Bool>

Whether to run the entity annotator.

=item * C<< $msg->run_intent_annotator() >> / C<< $msg->run_intent_annotator($value) >>

Type: C<Bool>

Whether to run the intent annotator.

=item * C<< $msg->run_issue_model_annotator() >> / C<< $msg->run_issue_model_annotator($value) >>

Type: C<Bool>

Whether to run the issue model annotator. A model should have already been
deployed for this to take effect.

=item * C<< $msg->issue_models() >> / C<< $msg->issue_models($value) >>

Type: C<String>

The issue model to run. If not provided, the most recently deployed topic
model will be used. The provided issue model will only be used for
inference if the issue model is deployed and if run_issue_model_annotator
is set to true. If more than one issue model is provided, only the first
provided issue model will be used for inference.

=item * C<< $msg->run_summarization_annotator() >> / C<< $msg->run_summarization_annotator($value) >>

Type: C<Bool>

Whether to run the summarization annotator.

=item * C<< $msg->summarization_config() >> / C<< $msg->summarization_config($value) >>

Type: C<Message> (L<Google::Cloud::Contactcenterinsights::V1::Resources::AnnotatorSelector::SummarizationConfig>)

Configuration for the summarization annotator.

=item * C<< $msg->run_qa_annotator() >> / C<< $msg->run_qa_annotator($value) >>

Type: C<Bool>

Whether to run the QA annotator.

=item * C<< $msg->qa_config() >> / C<< $msg->qa_config($value) >>

Type: C<Message> (L<Google::Cloud::Contactcenterinsights::V1::Resources::AnnotatorSelector::QaConfig>)

Configuration for the QA annotator.

=back

=head2 Google::Cloud::Contactcenterinsights::V1::Resources::QaQuestion

A single question to be scored by the Insights QA feature.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. The resource name of the question.
Format:
projects/{project}/locations/{location}/qaScorecards/{qa_scorecard}/revisions/{revision}/qaQuestions/{qa_question}

=item * C<< $msg->abbreviation() >> / C<< $msg->abbreviation($value) >>

Type: C<String>

Short, descriptive string, used in the UI where it's not practical
to display the full question body. E.g., "Greeting".

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The time at which this question was created.

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The most recent time at which the question was updated.

=item * C<< $msg->question_body() >> / C<< $msg->question_body($value) >>

Type: C<String>

Question text. E.g., "Did the agent greet the customer?"

=item * C<< $msg->answer_instructions() >> / C<< $msg->answer_instructions($value) >>

Type: C<String>

Instructions describing how to determine the answer.

=item * C<< $msg->answer_choices() >> / C<< $msg->answer_choices($value) >>

Type: C<Message> (L<Google::Cloud::Contactcenterinsights::V1::Resources::QaQuestion::AnswerChoice>)

A list of valid answers to the question, which the LLM must choose from.

=item * C<< $msg->tags() >> / C<< $msg->tags($value) >>

Type: C<String>

User-defined list of arbitrary tags for the question. Used for
grouping/organization and for weighting the score of each question.

=item * C<< $msg->order() >> / C<< $msg->order($value) >>

Type: C<Int32>

Defines the order of the question within its parent scorecard revision.

=item * C<< $msg->metrics() >> / C<< $msg->metrics($value) >>

Type: C<Message> (L<Google::Cloud::Contactcenterinsights::V1::Resources::QaQuestion::Metrics>)

Metrics of the underlying tuned LLM over a holdout/test set while fine
tuning the underlying LLM for the given question. This field will only be
populated if and only if the question is part of a scorecard revision that
has been tuned.

=item * C<< $msg->tuning_metadata() >> / C<< $msg->tuning_metadata($value) >>

Type: C<Message> (L<Google::Cloud::Contactcenterinsights::V1::Resources::QaQuestion::TuningMetadata>)

Metadata about the tuning operation for the question.This field will only
be populated if and only if the question is part of a scorecard revision
that has been tuned.

=back

=head2 Google::Cloud::Contactcenterinsights::V1::Resources::QaScorecard

A QaScorecard represents a collection of questions to be scored during
analysis.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. The scorecard name.
Format:
projects/{project}/locations/{location}/qaScorecards/{qa_scorecard}

=item * C<< $msg->display_name() >> / C<< $msg->display_name($value) >>

Type: C<String>

The user-specified display name of the scorecard.

=item * C<< $msg->description() >> / C<< $msg->description($value) >>

Type: C<String>

A text description explaining the intent of the scorecard.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The time at which this scorecard was created.

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The most recent time at which the scorecard was updated.

=back

=head2 Google::Cloud::Contactcenterinsights::V1::Resources::QaScorecardRevision

A revision of a QaScorecard.

Modifying published scorecard fields would invalidate existing scorecard
results — the questions may have changed, or the score weighting will make
existing scores impossible to understand. So changes must create a new
revision, rather than modifying the existing resource.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. The name of the scorecard revision.
Format:
projects/{project}/locations/{location}/qaScorecards/{qa_scorecard}/revisions/{revision}

=item * C<< $msg->snapshot() >> / C<< $msg->snapshot($value) >>

Type: C<Message> (L<Google::Cloud::Contactcenterinsights::V1::Resources::QaScorecard>)

The snapshot of the scorecard at the time of this revision's creation.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The timestamp that the revision was created.

=item * C<< $msg->alternate_ids() >> / C<< $msg->alternate_ids($value) >>

Type: C<String>

Output only. Alternative IDs for this revision of the scorecard, e.g.,
`latest`.

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Cloud::Contactcenterinsights::V1::QaScorecardRevision::State>)

Output only. State of the scorecard revision, indicating whether it's ready
to be used in analysis.

=back

=head3 Enum: QaScorecardRevision::State

=over 4

=item * C<STATE_UNSPECIFIED> => C<0>

=item * C<EDITABLE> => C<12>

=item * C<TRAINING> => C<2>

=item * C<TRAINING_FAILED> => C<9>

=item * C<READY> => C<11>

=item * C<DELETING> => C<7>

=item * C<TRAINING_CANCELLED> => C<14>

=back

=head2 Google::Cloud::Contactcenterinsights::V1::Resources::QaAnswer

An answer to a QaQuestion.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->qa_question() >> / C<< $msg->qa_question($value) >>

Type: C<String>

The QaQuestion answered by this answer.

=item * C<< $msg->conversation() >> / C<< $msg->conversation($value) >>

Type: C<String>

The conversation the answer applies to.

=item * C<< $msg->question_body() >> / C<< $msg->question_body($value) >>

Type: C<String>

Question text. E.g., "Did the agent greet the customer?"

=item * C<< $msg->answer_value() >> / C<< $msg->answer_value($value) >>

Type: C<Message> (L<Google::Cloud::Contactcenterinsights::V1::Resources::QaAnswer::AnswerValue>)

The main answer value, incorporating any manual edits if they exist.

=item * C<< $msg->tags() >> / C<< $msg->tags($value) >>

Type: C<String>

User-defined list of arbitrary tags. Matches the value from
QaScorecard.ScorecardQuestion.tags. Used for grouping/organization and
for weighting the score of each answer.

=item * C<< $msg->answer_sources() >> / C<< $msg->answer_sources($value) >>

Type: C<Message> (L<Google::Cloud::Contactcenterinsights::V1::Resources::QaAnswer::AnswerSource>)

List of all individual answers given to the question.

