=head2 Google::Cloud::Contactcenterinsights::V1::Resources::QaScorecardResult

The results of scoring a single conversation against a QaScorecard. Contains
a collection of QaAnswers and aggregate score.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. The name of the scorecard result.
Format:
projects/{project}/locations/{location}/qaScorecardResults/{qa_scorecard_result}

=item * C<< $msg->qa_scorecard_revision() >> / C<< $msg->qa_scorecard_revision($value) >>

Type: C<String>

The QaScorecardRevision scored by this result.

=item * C<< $msg->conversation() >> / C<< $msg->conversation($value) >>

Type: C<String>

The conversation scored by this result.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The timestamp that the revision was created.

=item * C<< $msg->agent_id() >> / C<< $msg->agent_id($value) >>

Type: C<String>

ID of the agent that handled the conversation.

=item * C<< $msg->qa_answers() >> / C<< $msg->qa_answers($value) >>

Type: C<Message> (L<Google::Cloud::Contactcenterinsights::V1::Resources::QaAnswer>)

Set of QaAnswers represented in the result.

=item * C<< $msg->score() >> / C<< $msg->score($value) >>

Type: C<Double>

The overall numerical score of the result, incorporating any manual edits
if they exist.

=item * C<< $msg->potential_score() >> / C<< $msg->potential_score($value) >>

Type: C<Double>

The maximum potential overall score of the scorecard. Any questions
answered using `na_value` are excluded from this calculation.

=item * C<< $msg->normalized_score() >> / C<< $msg->normalized_score($value) >>

Type: C<Double>

The normalized score, which is the score divided by the potential score.
Any manual edits are included if they exist.

=item * C<< $msg->qa_tag_results() >> / C<< $msg->qa_tag_results($value) >>

Type: C<Message> (L<Google::Cloud::Contactcenterinsights::V1::Resources::QaScorecardResult::QaTagResult>)

Collection of tags and their scores.

=item * C<< $msg->score_sources() >> / C<< $msg->score_sources($value) >>

Type: C<Message> (L<Google::Cloud::Contactcenterinsights::V1::Resources::QaScorecardResult::ScoreSource>)

List of all individual score sets.

=back

